-- Scout promotions were inspected: CP v151 already grants IgnoreTerrainCost.
-- Preserve those exact promotions; only supply the standard effect if absent.
INSERT INTO Unit_FreePromotions(UnitType,PromotionType)
 SELECT 'UNIT_PIGEON_CARRIER','PROMOTION_IGNORE_TERRAIN_COST'
 WHERE NOT EXISTS (SELECT 1 FROM Unit_FreePromotions f JOIN UnitPromotions p ON p.Type=f.PromotionType
 WHERE f.UnitType='UNIT_PIGEON_CARRIER' AND p.IgnoreTerrainCost=1);
INSERT INTO Unit_FreePromotions(UnitType,PromotionType) VALUES ('UNIT_PIGEON_CARRIER','PROMOTION_PIGEON_LOOKOUT');
